var t=`1163-enchiladas-verdes`;var a=`world-1163`;var n=`MX`;var r=`central-america-caribbean`;var o=4;var s=60;var l={en:`Enchiladas Verdes`,ua:`Зелені енчилади`};var c={en:`Enchiladas Verdes is a dish from Mexico prepared with tomatillo, serrano pepper, yellow onion, garlic. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Зелені енчилади, страва кухні країни Мексика, яку готують із таких продуктів: томатильйо, перець серрано, жовта цибуля, часник. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var d=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`tomatillo`,620,`g`],[`serrano-pepper`,2,`pcs`],[`yellow-onion`,150,`g`],[`garlic`,4,`clove`],[`canola-oil`,35,`ml`]]},{en:`Simmer the liquid and flavorings uncovered for about 12 minutes until reduced and concentrated.`,ua:`Уварюйте рідину з приправами без кришки приблизно 12 хвилин до насичення та загустіння.`,t:[`reducing-sauce`],m:12,i:[[`chicken-stock`,380,`ml`]]},{en:`Poach the chicken completely until it reaches 74°C, then shred and place inside warmed tortillas before coating with green sauce.`,ua:`Повністю зваріть курку до 74°C, розберіть на волокна й загорніть у підігріті тортильї перед додаванням зеленого соусу.`,t:[`poaching`],m:24,i:[[`chicken-thigh`,460,`g`],[`water`,650,`ml`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:9,i:[[`corn-tortillas`,12,`pcs`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:6,i:[[`queso-fresco`,150,`g`],[`sour-cream`,140,`g`],[`cilantro`,20,`g`]]}];var h={slug:t,id:a,country:`MX`,region:r,servings:4,minutes:60,title:l,text:c,steps:d};export{n as country,h as default,a as id,s as minutes,r as region,o as servings,t as slug,d as steps,c as text,l as title};